#include "gtest/gtest.h"
#include "database.h"
#include "scheduler_db.h"
#include "sqlite_db.hpp"
#include "logger.h"

// SqliteDatabase is a singleton. We must initialize it ONCE
// before any test runs. All tests share the same :memory: database.
class DatabaseTest : public ::testing::Test {
  protected:
    static void SetUpTestSuite() {
        SqliteDatabase::init(":memory:");
        db_ = std::make_unique<SchedulerDatabase>();

        Worker w;
        w.cpu_cores = 4;
        w.mem_size = 8192.0f;
        w.disk_size = 102400.0f;
        w.cpu_freq = 2.5f;
        w.os = "Linux";
        w.name = "test-worker";
        w.status = "active";
        worker_id_ = db_->insert_worker(w);
    }

    static std::unique_ptr<SchedulerDatabase> db_;
    static int worker_id_;
};

std::unique_ptr<SchedulerDatabase> DatabaseTest::db_ = nullptr;
int DatabaseTest::worker_id_ = 0;

TEST_F(DatabaseTest, InsertAndRetrieveJob) {
    int job_id = db_->insert_job("stress_cpu", R"({"cores":2,"duration_ms":5000})", 1);
    EXPECT_GT(job_id, 0);

    Job job = db_->get_job_by_id(job_id);
    EXPECT_EQ(job.id, job_id);
    EXPECT_EQ(job.job_type, "stress_cpu");
    EXPECT_EQ(job.status, "not started");
    EXPECT_EQ(job.client_id, 1);
}

TEST_F(DatabaseTest, QueryJobsByStatus) {
    int j1 = db_->insert_job("stress_cpu", "{}", 1);
    int j2 = db_->insert_job("stress_mem", "{}", 1);

    db_->update_job_status(j2, "completed");

    auto not_started = db_->get_jobs_by_status("not started");
    bool j1_found = false;
    for (const auto& j : not_started) {
        if (j.id == j1) j1_found = true;
        EXPECT_NE(j.id, j2);
    }
    EXPECT_TRUE(j1_found);
}

